208	/// Ctrl / Alt 的 evdev 键码,用于识别"Ctrl+Alt 交还鼠标"这一组合
209	const KEY_LEFTCTRL: u16 = 29;
210	const KEY_RIGHTCTRL: u16 = 97;
211	const KEY_LEFTALT: u16 = 56;
212	const KEY_RIGHTALT: u16 = 100;
213	
214	fn is_ctrl(code: u16) -> bool {
215	    code == KEY_LEFTCTRL || code == KEY_RIGHTCTRL
216	}
217	
218	fn is_alt(code: u16) -> bool {
219	    code == KEY_LEFTALT || code == KEY_RIGHTALT
220	}
221	
222	/// Ctrl+Alt 组合的触发判定:两者都按住时,按下的那一方触发一次切换。
223	/// 这样一次组合只会切换一次,按住不放也不会连发。
224	fn ctrl_alt_chord(code: u16, pressed: bool, ctrl_down: bool, alt_down: bool) -> bool {
225	    pressed && ctrl_down && alt_down && (is_ctrl(code) || is_alt(code))
226	}
