380	/// 把 `codes` 写进一条组合键步骤的键表。
381	///
382	/// 从第 0 格开始录 = "这一整组就是这一轮按下的键" ⇒ **整份替换**，不留旧尾巴
383	/// （否则从 4 键改成 2 键时会剩下两个 0，宏执行时会去按一个无效键码）。
384	/// 从第 1 格起录 = 只改那一格，缺位按 [`MACRO_COMBO_MAX_KEYS`] 上限补长。
385	fn write_combo_keys(dst: &mut Vec<u16>, slot: usize, codes: &[u16]) {
386	    if codes.is_empty() {
387	        return;
388	    }
389	    if slot == 0 {
390	        dst.clear();
391	        dst.extend(codes.iter().take(MACRO_COMBO_MAX_KEYS));
392	        return;
393	    }
394	    for (i, code) in codes.iter().enumerate() {
395	        let at = slot + i;
396	        if at < dst.len() {
397	            dst[at] = *code;
398	        } else if at < MACRO_COMBO_MAX_KEYS {
399	            dst.push(*code);
400	        }
401	    }
402	}
