///
/// 左右 Ctrl/Alt 都算([`is_ctrl`]/[`is_alt`] 覆盖 29/97/56/100);
/// 默认配置里两个键位都是空集合 ⇒ 返回 `None` ⇒ 行为与修复前逐字一致。
pub(crate) fn chord_yield_reason(aim: &Aim) -> Option<&'static str> {
    for (ks, name) in [
        (&aim.toggle_key, "FPS 模式开关键"),
