    fn custom_wheel_kind_switches_preserve_directions() {", "old_string": "    /// Ctrl+Alt:一次组合只切换一次,松开后再按才会再次触发
    #[test]
    fn ctrl_alt_chord_fires_once_per_press() {
        // 只按 Ctrl:不触发
        assert!(!ctrl_alt_chord(KEY_LEFTCTRL, true, true, false));
        // 在按住 Ctrl 的基础上按下 Alt:触发
        assert!(ctrl_alt_chord(KEY_LEFTALT, true, true, true));
        // Alt 保持按住时的重复按下事件:仍然算一次触发(由调用方取反,不会连发)
        assert!(ctrl_alt_chord(KEY_LEFTALT, true, true, true));
        // 松开 Alt:不触发
        assert!(!ctrl_alt_chord(KEY_LEFTALT, false, true, false));

        // 同时按住 Ctrl+Alt 时按其它键:不触发
        assert!(!ctrl_alt_chord(30, true, true, true)); // KEY_A
        // 右键的 Ctrl / Alt 同样识别
        assert!(ctrl_alt_chord(KEY_RIGHTCTRL, true, true, true));
        assert!(ctrl_alt_chord(KEY_RIGHTALT, true, true, true));
    }

    /// DF-12:内置 Ctrl+Alt 与"可绑定系统键"的冲突判定。
    ///
    /// 用户把 FPS 开关键 / 按住才退出键显式绑成 Ctrl、Alt 或含它们的组合键时,
    /// 内置手势必须整体让位;**只看配置**——用户绑的是 Ctrl,冲突发生在随后按下的
    /// Alt 那一下,所以判据绝不能写成"本次按下的键属于某个 KeySet"。
    #[test]
    fn chord_yield_reason_only_when_a_system_key_uses_ctrl_or_alt() {
        // 默认(两个键位都没绑):内置手势照旧生效
        let a = aim_at(0.5, 0.5);
        assert_eq!(chord_yield_reason(&a), None, "没绑系统键时内置手势必须照旧");
        assert!(
            ctrl_alt_chord(KEY_LEFTALT, true, true, true),
            "前置的 ctrl_alt_chord 判定本身不受影响"
        );

        // FPS 开关键绑成左 Ctrl:让位,并说明是被谁占了
        let mut a = aim_at(0.5, 0.5);
        a.toggle_key = KeySet::single(KEY_LEFTCTRL);
        assert_eq!(chord_yield_reason(&a), Some("FPS 模式开关键"));

        // 按住才退出绑成左 Alt:让位
        let mut a = aim_at(0.5, 0.5);
        a.suspend_key = KeySet::single(KEY_LEFTALT);
        assert_eq!(chord_yield_reason(&a), Some("按住才退出"));

        // 组合键 Ctrl+Z(29+44)同样命中:判据看的是"配置里含 Ctrl/Alt",
        // 不是本次按下的那一个键
        let mut a = aim_at(0.5, 0.5);
        a.toggle_key = KeySet::from_keys([KEY_LEFTCTRL, 44]);
        assert_eq!(chord_yield_reason(&a), Some("FPS 模式开关键"));

        // 右 Ctrl / 右 Alt 也算
        let mut a = aim_at(0.5, 0.5);
        a.suspend_key = KeySet::single(KEY_RIGHTCTRL);
        assert_eq!(chord_yield_reason(&a), Some("按住才退出"));
