/// 交还鼠标后瞄准不生效
#[test]
fn released_blocks_aim() {
    let aim = aim_at(0.1, 0.1);
    let mut st = AimState::default();
    st.mode_active = true;
    assert!(aim_active(&aim, &st));
    st.released = true;
    assert!(!aim_active(&aim, &st));
}

