    fn delivered_rotation(cmds: &[crate::control::ControlCmd]) -> f32 {
        use crate::control::{ACTION_DOWN, ACTION_MOVE, ACTION_UP, ControlCmd};
        let mut total = 0.0f32;
        let mut last: Option<(i32, i32)> = None;
        for c in cmds {
            if let ControlCmd::Touch { action, x, y, .. } = c {
                let (x, y) = (*x as i32, *y as i32);
                match *action {
                    ACTION_DOWN => last = Some((x, y)),
                    ACTION_MOVE => {
                        if let Some((px, py)) = last {
                            total += (((x - px) as f32).powi(2) + ((y - py) as f32).powi(2)).sqrt();
                        }
                        last = Some((x, y));
                    }
                    ACTION_UP => last = None,
                    _ => {}
                }
            }
        }
