/// - 成立但期间来过新事件 ⇒ 从 1 重新数(刚有动静,不能算"早就没消息了")
fn next_strike(prev: u8, lost_now: bool, seen_changed: bool) -> u8 {
    if !lost_now {
        0
    } else if seen_changed {
