/// 鼠标键补发抬起前的连续确认拍数(见 [`reconcile_with`] 的说明)。
const MOUSE_RELEASE_STRIKES: u8 = 2;

/// 连续确认计数的推进(纯函数,便于单测)。
/// - 这一轮不成立(系统说按下 / 还没过宽限 / 没有按下心跳)⇒ 归零
/// - 成立且这期间**没有新事件**(`last_seen` 没变)⇒ +1
/// - 成立但期间来过新事件 ⇒ 从 1 重新数(刚有动静,不能算"早就没消息了")
fn next_strike(prev: u8, lost_now: bool, seen_changed: bool) -> u8 {
    if !lost_now {
        0
    } else if seen_changed {
        1
    } else {
        prev.saturating_add(1)
    }
}

/// 鼠标键这一轮能不能真的补发抬起。
///
/// 两条同时成立(比"单次读数为 0 就动手"严格,理由见 [`reconcile_with`]):
/// ①读通道自证在工作(`channel_healthy`);
/// ②连续命中嫌疑满 [`MOUSE_RELEASE_STRIKES`] 拍,且期间没有新事件。
fn mouse_release_confirmed(channel_healthy: bool, strikes: u8) -> bool {
    channel_healthy && strikes >= MOUSE_RELEASE_STRIKES
}
